-- A：每个条件分别开新事务。
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;
START TRANSACTION;
SELECT * FROM range_probe FORCE INDEX(ix_k) WHERE k>=6 AND k<9 FOR UPDATE;
-- 本组结束 ROLLBACK 后再另开事务执行：
-- SELECT * FROM range_probe FORCE INDEX(ix_k) WHERE k BETWEEN 6 AND 9 FOR UPDATE;

INSERT INTO range_probe VALUES(100,5.5);
-- 下一次独立事务：INSERT INTO range_probe VALUES(100,6.5);
-- 下一次独立事务：INSERT INTO range_probe VALUES(100,8.5);
-- 下一次独立事务：INSERT INTO range_probe VALUES(100,9.0);
-- 下一次独立事务：INSERT INTO range_probe VALUES(100,9.5);
